info = context.security_info(symbol)
if info and info.get('is_st') is True:
    print('发现 ST 状态')

reports = context.financials(symbol)
for report in reports:
    print(report.get('report_period'), report.get('adjusted_net_profit'))

value = context.valuation(symbol)
if value and value.get('pe_ratio') is not None:
    print(value['pe_ratio'])

ma30 = context.factor('technical.ma', symbol=symbol, window=30)
if ma30['available']:
    print(ma30['value'])

price = context.current_price(symbol)
if price is not None and price <= Decimal('10.50'):
    print('达到买点')
